// GENERATED — do not hand-edit. Produced from `public/map.svg` (the designer's
// dot-grid US map) by clustering its 374 coloured dots into the six states
// Fortiva names in `content/site.ts`.
//
// The map is split across two assets, and the split is the whole performance
// story:
//
//   public/map-base.svg   the 3,989 dots for the other 44 states, kept as ONE
//                         <path> and drawn as a plain <img>. Nothing about it
//                         ever changes, so it costs nothing to keep out of the
//                         JS bundle and it caches like any other image.
//   this file             only the six interactive states — 374 dot paths. Small
//                         enough to inline, which is what lets React address
//                         each dot individually.
//
// Both halves share the 736 x 542 viewBox of the original file, so the <img> and
// the <svg> overlay stay in register at any width. Every `d` string below is
// copied verbatim from map.svg.
//
// ── Colour ──────────────────────────────────────────────────────────────────
// map.svg is the only source of colour for this section. Nothing in the CSS or
// the components names a hex: MAP_FILLS below reaches the DOM as the --fmap-ink
// custom property on each state group, and the dots, the highlight ring, the
// glow and the idle ping all read it from there. The chips read it too, so the
// list beside the map is tinted by the same values.
//
// scripts/build-map.mjs re-derives MAP_FILLS and rebuilds public/map-base.svg
// straight from public/map.svg, and it runs on every `npm run dev` and
// `npm run build`. So recolouring the artwork is the whole job — the section
// follows on the next start, with no code change and no way to drift from its
// source.

export interface MapDot {
  /** Path data, verbatim from map.svg, in the shared 736 x 542 viewBox. */
  d: string
  /**
   * 0 at the state's centre, 1 at its furthest dot. Drives the outward ripple
   * when a state activates (see the `--t` rules in styles/index.css) — purely
   * presentational.
   */
  t: number
}

export interface MapStateShape {
  code: string
  name: string
  dots: MapDot[]
  /**
   * Pointer target: the union of this state's dots dilated by ~2/3 of the grid
   * spacing, so the gaps between dots are covered and the region hugs the
   * artwork rather than the true state border. Doubles as the highlight ring
   * and the glow, which is why it's one shape rather than a set of hit boxes.
   */
  hit: string
  /** Horizontal centre of the dot cluster — the tooltip's x anchor. */
  cx: number
  /** Top of the dot cluster — the tooltip's y anchor, so a label always sits
   *  above the state it names rather than on top of it. */
  ty: number
}

export const MAP_VIEWBOX = { width: 736, height: 542 } as const

/**
 * The lean-in. While any state is active the whole map scales up about a point in
 * the middle of the six-state cluster, which enlarges the region being explored
 * without ever moving it.
 *
 * 1.05 is not a taste call — it's the ceiling. The map floats with no container
 * to clip against, so any scale that pushes a dot past the viewBox would need a
 * hard edge or a mask to hide it. The artwork's own margin is ~4.6 per cent (dots
 * start at x=34 of 736, y=26 of 542), and scaling about this off-centre origin
 * spends that margin fastest on the west coast: at 1.05 the far-left dot lands at
 * x=7, still inside. Anything more and the map starts cutting itself off. The size
 * the region really needed came from dropping the card and widening the column
 * instead, which is permanent rather than only true on hover.
 *
 * StateMap applies this as a CSS transform to the <img> and <svg> together, and
 * reuses the same numbers to keep the (unscaled) tooltip pinned to its state.
 */
export const MAP_FOCUS = { x: 570, y: 330, scale: 1.05 } as const

