/** Lookup by the two-letter code used in `content/site.ts`. */
export const mapStateByCode: Record<string, MapStateShape> = Object.fromEntries(
  mapStates.map((s) => [s.code, s]),
)

// ── Regenerating the geometry ────────────────────────────────────────────────
// Recolouring needs nothing but `npm run dev` (see above). Redrawing does: if the
// artwork's shapes change, the six states have to be re-clustered, and
// build-map.mjs will say so rather than guess.
//
// map.svg carries no ids or groups — the only thing separating the six states from
// the other forty-four is fill colour — so the split was done geometrically: fit
// d3-geo's albersUsa projection to the dot cloud, invert each dot back to a
// lon/lat, and point-in-polygon it against us-atlas state boundaries. Two passes,
// and neither one names a hex:
//
//   1. assign every coloured dot to whichever of the six states contains it
//      (nearest border if it lands just outside, as coastal dots do)
//   2. take each state's colour to be the majority fill of the dots it just
//      collected, then move any dot whose own fill disagrees to the nearest state
//      that does wear it
//
// Pass 2 is what makes a border dot impossible to misfile, and it's why swapping
// which tier is navy and which is gold changed nothing here: the rule reads the
// grouping out of the artwork instead of being told it.
